"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["2307"],{2934(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>h,frontMatter:()=>a,contentTitle:()=>o,toc:()=>c,assets:()=>d});var i=JSON.parse('{"id":"networks/switching-fundamentals","title":"Switching Fundamentals","description":"The switch is the workhorse device of every modern wired LAN. Understanding precisely how it learns, forwards, and floods frames \u2014 and the domain concepts (collision/broadcast) this creates \u2014 is foundational to virtually everything else in Layer 2 and Layer 3 networking.","source":"@site/docs/networks/12-switching-fundamentals.md","sourceDirName":"networks","slug":"/networks/switching-fundamentals","permalink":"/Mindstack/docs/networks/switching-fundamentals","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":12,"frontMatter":{"title":"Switching Fundamentals","sidebar_label":"Switching Fundamentals","sidebar_position":12},"sidebar":"networkSidebar","previous":{"title":"MAC Addressing","permalink":"/Mindstack/docs/networks/mac-addressing"},"next":{"title":"vlans","permalink":"/Mindstack/docs/networks/vlans"}}'),s=t(4848),r=t(8453);let a={title:"Switching Fundamentals",sidebar_label:"Switching Fundamentals",sidebar_position:12},o="Switching Fundamentals",d={},c=[{value:"How a Switch Operates \u2014 Learn, Forward, Flood",id:"how-a-switch-operates--learn-forward-flood",level:2},{value:"Worked Example",id:"worked-example",level:3},{value:"Switch Forwarding Methods",id:"switch-forwarding-methods",level:2},{value:"Collision Domains",id:"collision-domains",level:2},{value:"Broadcast Domains",id:"broadcast-domains",level:2},{value:"Switch Port States and Interface Basics (Cisco IOS)",id:"switch-port-states-and-interface-basics-cisco-ios",level:2},{value:"Multicast Optimization \u2014 IGMP Snooping",id:"multicast-optimization--igmp-snooping",level:2},{value:"Switch Types and Roles in Network Design",id:"switch-types-and-roles-in-network-design",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function l(e){let n={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"switching-fundamentals",children:"Switching Fundamentals"})}),"\n",(0,s.jsx)(n.p,{children:"The switch is the workhorse device of every modern wired LAN. Understanding precisely how it learns, forwards, and floods frames \u2014 and the domain concepts (collision/broadcast) this creates \u2014 is foundational to virtually everything else in Layer 2 and Layer 3 networking."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"how-a-switch-operates--learn-forward-flood",children:"How a Switch Operates \u2014 Learn, Forward, Flood"}),"\n",(0,s.jsxs)(n.p,{children:["A switch builds and maintains a ",(0,s.jsx)(n.strong,{children:"MAC address table"})," (also called a CAM table \u2014 Content Addressable Memory table, referring to the specialized hardware used to implement it at line rate) through a simple but powerful process:"]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'1. LEARN: When a frame arrives on a port, the switch reads the SOURCE\n   MAC address and records: "this MAC is reachable via this port,"\n   along with a timestamp.\n\n2. FORWARD or FLOOD: The switch reads the DESTINATION MAC address:\n   - If the destination MAC is already in the table \u2192 forward the\n     frame OUT ONLY that specific port (unicast, efficient)\n   - If the destination MAC is NOT in the table (unknown unicast) \u2192\n     flood the frame out ALL ports except the one it arrived on\n   - If the destination is the broadcast address (FF:FF:FF:FF:FF:FF)\n     \u2192 always flood out all ports (except the source port)\n   - If the destination is a multicast address \u2192 flood by default,\n     unless IGMP snooping is configured to optimize this (see below)\n\n3. AGE OUT: Entries in the MAC table expire after a period of\n   inactivity (default is commonly 300 seconds / 5 minutes on most\n   platforms) to keep the table accurate as devices move or disconnect.\n'})}),"\n",(0,s.jsx)(n.h3,{id:"worked-example",children:"Worked Example"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"Switch with 4 ports, empty MAC table:\n\nFrame arrives on Port 1, Source=AAAA, Dest=BBBB\n  \u2192 Switch learns: AAAA is on Port 1\n  \u2192 BBBB not yet known \u2192 FLOOD to Ports 2, 3, 4\n\nFrame arrives on Port 3, Source=BBBB, Dest=AAAA (BBBB's reply)\n  \u2192 Switch learns: BBBB is on Port 3\n  \u2192 AAAA IS known (Port 1) \u2192 forward ONLY to Port 1\n\nNow both AAAA and BBBB are known. Any future frame between them is\nforwarded directly, port to port, with NO flooding \u2014 efficient,\npredictable, and (critically) private from other ports' perspective.\n"})}),"\n",(0,s.jsx)(n.p,{children:"This learn/forward/flood behavior is why switches dramatically outperform hubs: a hub blindly repeats every frame out every port regardless of destination, while a switch quickly learns the topology and sends frames only where they need to go."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"switch-forwarding-methods",children:"Switch Forwarding Methods"}),"\n",(0,s.jsx)(n.p,{children:"How quickly and thoroughly a switch examines a frame before forwarding it involves a real engineering tradeoff between speed and error-checking:"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"Store-and-Forward \u2014 receives the ENTIRE frame, verifies the FCS\n  (checksum) for errors, THEN forwards. \n  + Catches and drops corrupted frames before they waste bandwidth\n    elsewhere on the network\n  - Highest latency (must wait for the whole frame before forwarding\n    any of it)\n  Most common method on modern enterprise switches \u2014 the latency cost\n  is negligible at modern speeds, and the error-checking benefit is\n  valuable.\n\nCut-Through \u2014 begins forwarding as soon as the DESTINATION MAC address\n  is read (just the first 6 bytes after the preamble/SFD), without\n  waiting for the rest of the frame or checking the FCS.\n  + Lowest possible latency \u2014 critical for some high-frequency trading\n    and specialized low-latency datacenter applications\n  - Forwards corrupted frames (errors aren't detected until later,\n    if at all, by the receiving device)\n\nFragment-Free \u2014 a compromise: reads the first 64 bytes (the minimum\n  legal Ethernet frame size) before forwarding, catching most collision-\n  related fragments (which are typically smaller than 64 bytes) while\n  still achieving lower latency than full store-and-forward.\n"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"collision-domains",children:"Collision Domains"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"A collision domain is the set of devices where a frame transmitted by\none device could collide with a frame transmitted by another.\n\nHub:    ALL ports share ONE collision domain (a frame from any port\n        can collide with a frame from any other port \u2014 see Ethernet\n        Fundamentals for why CSMA/CD existed to manage this)\n\nSwitch: EVERY PORT is its OWN separate collision domain. Because each\n        switch port operates full-duplex with a dedicated, dedicated\n        transmit/receive pair to exactly one device (or, historically,\n        to a hub feeding multiple devices into that one collision\n        domain), true collisions on modern switched full-duplex links\n        are physically impossible.\n\nRouter: each interface is also its own collision domain (irrelevant\n        to discuss further since routers don't typically share a\n        segment with multiple hosts the way hubs/legacy switches might)\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"Quick count exercise:\n[PC]\u2500\u2500[Switch 8-port]\u2500\u2500[PC]\n                \u2502\n              [PC]\n\nA switch with 3 connected devices on 3 separate ports = 3 separate\ncollision domains (one per active port). If a hub were plugged into\none of those switch ports with 4 PCs hanging off it, that hub's 4 PCs\nwould all share ONE collision domain (the hub itself), making the\nTOTAL collision domain count for this topology = 3 (switch ports) - 1\n(the port now feeding the hub) + 1 (the hub's shared domain) = 3 total.\n"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"broadcast-domains",children:"Broadcast Domains"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"A broadcast domain is the set of devices that will receive a broadcast\nframe (destination FF:FF:FF:FF:FF:FF) sent by any device within it.\n\nSwitch (without VLANs): ALL ports on the switch are in ONE broadcast\n  domain \u2014 a broadcast from any device reaches every other device\n  connected to that switch.\n\nSwitch (with VLANs): each VLAN is its OWN separate broadcast domain \u2014\n  a broadcast in VLAN 10 does NOT reach devices in VLAN 20, even\n  though they're physically connected to the same switch hardware\n  (full detail in VLANs).\n\nRouter: each router INTERFACE represents a boundary between broadcast\n  domains \u2014 routers do NOT forward broadcasts between interfaces by\n  default (this is one of the fundamental, defining differences\n  between Layer 2 switching and Layer 3 routing).\n"})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"Why broadcast domain size matters: every device in a broadcast domain\nmust process every broadcast frame sent within it (ARP requests, DHCP\ndiscovers, etc.), consuming CPU even on devices that aren't the\nintended recipient. A broadcast domain that's too large (\"broadcast\nstorm\" territory, or just chronic background overhead from a large\nflat network) degrades performance for everyone in it \u2014 this is the\ncore motivating reason VLANs exist (see VLANs) and why network\ndesigners deliberately keep broadcast domains reasonably small.\n"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"switch-port-states-and-interface-basics-cisco-ios",children:"Switch Port States and Interface Basics (Cisco IOS)"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"! Viewing the MAC address table\nSwitch# show mac address-table\nSwitch# show mac address-table dynamic\nSwitch# show mac address-table interface gi0/1\n\n! Basic interface configuration\nSwitch(config)# interface gigabitethernet 0/1\nSwitch(config-if)# description Link to PC-Alice\nSwitch(config-if)# speed auto\nSwitch(config-if)# duplex auto\nSwitch(config-if)# no shutdown\n\n! Static MAC entry (rarely needed, occasionally used for security/troubleshooting)\nSwitch(config)# mac address-table static 0011.2233.4455 vlan 10 interface gi0/1\n\n! Adjusting the MAC address table aging timer\nSwitch(config)# mac address-table aging-time 600\n"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"multicast-optimization--igmp-snooping",children:"Multicast Optimization \u2014 IGMP Snooping"}),"\n",(0,s.jsx)(n.p,{children:"By default, a switch treats multicast traffic the same as broadcast: flood it out every port. This is wasteful when only a subset of devices actually want the multicast stream (e.g. an IPTV channel)."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'IGMP Snooping \u2014 the switch "listens in" (snoops) on IGMP (Internet\n  Group Management Protocol) messages exchanged between hosts and\n  routers to learn WHICH ports actually have devices that joined a\n  given multicast group, and forwards multicast traffic ONLY to those\n  ports instead of flooding it everywhere \u2014 a significant efficiency\n  improvement on switches carrying multicast video/streaming traffic.\n'})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"switch-types-and-roles-in-network-design",children:"Switch Types and Roles in Network Design"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'Access Layer Switch \u2014 connects end devices (PCs, phones, APs) directly;\n  typically has many lower-speed ports (e.g. 48x 1GbE) and fewer\n  higher-speed uplinks (e.g. 2-4x 10GbE) toward the distribution layer\n\nDistribution Layer Switch \u2014 aggregates multiple access switches,\n  often the first point where Layer 3 routing/VLAN inter-routing\n  happens, enforces policy (ACLs, QoS)\n\nCore Layer Switch \u2014 high-speed backbone, moves traffic between\n  distribution switches as fast as possible, generally avoids complex\n  policy enforcement to keep forwarding decisions simple and fast\n\nThis three-tier model (Access-Distribution-Core) is the classic,\nstill widely-taught Cisco hierarchical network design model. Many\nmodern datacenter designs instead use a flatter "spine-leaf" topology\n(every leaf switch connects to every spine switch) for more predictable,\nnon-blocking performance \u2014 a more recent architectural evolution\ncovered further in datacenter/cloud networking contexts.\n'})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:'"How many collision domains" and "how many broadcast domains" are extremely common exam-style and real design questions \u2014 the fast rule: collision domains = count every switch/router port; broadcast domains = count every VLAN/router interface boundary.'}),"\n",(0,s.jsx)(n.li,{children:"Store-and-forward is the right default for virtually all enterprise/campus switching \u2014 only consider cut-through switching for specialized, latency-critical datacenter applications where you fully understand and accept the tradeoff of forwarding some corrupted frames."}),"\n",(0,s.jsx)(n.li,{children:'A device\'s MAC address showing up on multiple switch ports in rapid succession ("flapping") in the MAC table is a strong signal of either a Layer 2 loop or a duplicate/spoofed MAC \u2014 investigate immediately, as loops can quickly degrade an entire network.'}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Switches learn MAC-to-port mappings by inspecting source addresses, then forward known-destination frames directly and flood unknown-destination/broadcast frames."}),"\n",(0,s.jsx)(n.li,{children:"Store-and-forward (verify FCS, higher latency) is standard; cut-through (forward immediately, lower latency, no error checking) is reserved for specialized low-latency use cases."}),"\n",(0,s.jsx)(n.li,{children:"Every switch port is its own collision domain on modern full-duplex switching \u2014 true collisions are essentially extinct on properly configured modern networks."}),"\n",(0,s.jsx)(n.li,{children:"Every VLAN (or router interface) is its own broadcast domain \u2014 switches do NOT segment broadcast domains by port alone; that requires VLANs."}),"\n",(0,s.jsx)(n.li,{children:"IGMP snooping prevents multicast traffic from being treated as broadcast-style flooding, forwarding it only to ports that actually requested the stream."}),"\n",(0,s.jsx)(n.li,{children:"The Access-Distribution-Core hierarchical model remains the standard campus design pattern, while spine-leaf has become dominant in modern datacenter design."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}},8453(e,n,t){t.d(n,{R:()=>a,x:()=>o});var i=t(6540);let s={},r=i.createContext(s);function a(e){let n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(r.Provider,{value:n},e.children)}}}]);